import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const WORD = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function int(v, field, least) {
  if (!UINT.test(v) || BigInt(v) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(v)
}

function makeBucket(name, cap, refill, per) {
  const states = new Map()
  const max = cap * per
  return {
    name,
    advance(key, t) {
      let s = states.get(key)
      if (!s) { s = { v: max, last: t }; states.set(key, s); return s }
      s.v += refill * (t - s.last)
      if (s.v > max) s.v = max
      s.last = t
      return s
    },
    allows(key) { return states.get(key).v >= per },
    record(key) { states.get(key).v -= per },
  }
}

function makeWindow(name, limit, span) {
  const states = new Map()
  return {
    name,
    advance(key, t) {
      let s = states.get(key)
      if (!s) { s = { ticks: [], t }; states.set(key, s) }
      s.t = t
      const cut = t - span
      s.ticks = s.ticks.filter((x) => x > cut)
    },
    allows(key) { return BigInt(states.get(key).ticks.length) < limit },
    record(key) { const s = states.get(key); s.ticks.push(s.t) },
  }
}

function run(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const out = []
  const stats = new Map()
  let started = false
  let prev = null
  let prevStr = ''
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const w = line.split(/\s+/)
    try {
      const d = w[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        if (started) throw new Fail('declarations must come before the first event')
      }
      if (d === 'bucket') {
        if (w.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (!WORD.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        const cap = int(w[2], 'capacity', 1), refill = int(w[3], 'refill', 0), per = int(w[4], 'per', 1)
        if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], makeBucket(w[1], cap, refill, per))
      } else if (d === 'window') {
        if (w.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (!WORD.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        const limit = int(w[2], 'limit', 0), span = int(w[3], 'span', 1)
        if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], makeWindow(w[1], limit, span))
      } else if (d === 'route') {
        if (w.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!WORD.test(w[1])) throw new Fail(`invalid route prefix ${w[1]}`)
        if (routes.has(w[1])) throw new Fail(`prefix ${w[1]} is routed twice`)
        for (const p of w.slice(2)) if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
        routes.set(w[1], w.slice(2).map((p) => policies.get(p)))
      } else if (d === 'event') {
        if (w.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = int(w[1], 'tick', 0)
        const key = w[2]
        if (!WORD.test(key)) throw new Fail(`invalid key ${key}`)
        if (prev !== null && tick < prev) throw new Fail(`tick ${w[1]} is before tick ${prevStr}`)
        started = true
        prev = tick; prevStr = w[1]
        let best = null
        for (const [p, ps] of routes) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
        let denied = null
        if (best !== null) {
          const ps = routes.get(best)
          for (const p of ps) p.advance(key, tick)
          for (const p of ps) if (!p.allows(key)) { denied = p; break }
          if (!denied) for (const p of ps) p.record(key)
        }
        const st = stats.get(key) || { a: 0, d: 0 }
        stats.set(key, st)
        if (denied) st.d++; else st.a++
        out.push(denied ? `${w[1]} ${key} deny ${denied.name}` : `${w[1]} ${key} allow`)
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  let res = '', ta = 0, td = 0
  for (const k of [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    const s = stats.get(k)
    ta += s.a; td += s.d
    res += `${k} allowed=${s.a} denied=${s.d}\n`
  }
  return res + `total allowed=${ta} denied=${td}\n`
}

try {
  process.stdout.write(run(readFileSync(0, 'utf8')))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
